15	/// A Bloom Filter.
16	///
17	/// # Minimum kernel version
18	///
19	/// The minimum kernel version required to use this feature is 5.16.
20	///
21	/// # Examples
22	///
23	/// ```no_run
24	/// # use assert_matches::assert_matches;
25	/// # let mut bpf = aya::Ebpf::load(&[])?;
26	/// use aya::maps::MapError;
27	/// use aya::maps::bloom_filter::BloomFilter;
28	///
29	/// let mut bloom_filter = BloomFilter::try_from(bpf.map_mut("BLOOM_FILTER").unwrap())?;
30	///
31	/// bloom_filter.insert(1, 0)?;
32	///
33	/// assert_matches!(bloom_filter.contains(&mut 1, 0), Ok(()));
34	/// assert_matches!(bloom_filter.contains(&mut 2, 0), Err(MapError::ElementNotFound));
35	///
36	/// # Ok::<(), aya::EbpfError>(())
37	/// ```
38	#[doc(alias = "BPF_MAP_TYPE_BLOOM_FILTER")]
39	#[derive(Debug)]
40	pub struct BloomFilter<T, V: Pod> {
41	    pub(crate) inner: T,
42	    _v: PhantomData<V>,
43	}
44	
45	impl<T: Borrow<MapData>, V: Pod> BloomFilter<T, V> {
46	    pub(crate) fn new(map: T) -> Result<Self, MapError> {
47	        let data = map.borrow();
48	        check_v_size::<V>(data)?;
49	
50	        Ok(Self {
51	            inner: map,
52	            _v: PhantomData,
53	        })
54	    }
55	
56	    /// Query the existence of the element.
57	    pub fn contains(&self, value: &mut V, flags: u64) -> Result<(), MapError> {
58	        let fd = self.inner.borrow().fd().as_fd();
59	
60	        match bpf_map_lookup_elem_ptr::<u32, _>(fd, None, value, flags).map_err(|io_error| {
61	            SyscallError {
62	                call: "bpf_map_lookup_elem",
63	                io_error,
64	            }
65	        })? {
66	            None => Err(MapError::ElementNotFound),
67	            Some(()) => Ok(()),
68	        }
69	    }
70	}
71	
72	impl<T: BorrowMut<MapData>, V: Pod> BloomFilter<T, V> {
73	    /// Inserts a value into the map.
74	    pub fn insert(&mut self, value: impl Borrow<V>, flags: u64) -> Result<(), MapError> {
75	        let fd = self.inner.borrow_mut().fd().as_fd();
76	        bpf_map_push_elem(fd, value.borrow(), flags)
77	            .map_err(|io_error| SyscallError {
78	                call: "bpf_map_push_elem",
79	                io_error,
80	            })
81	            .map_err(Into::into)
82	    }
83	}
