77	///
78	/// Upon pinning a map, a file representation is created for the map,
79	/// so that the map can be alive and retrievable across sessions.
80	#[repr(u32)]
81	#[derive(Copy, Clone, Debug, PartialEq, Eq, Default)]
82	pub enum PinningType {
83	    /// No pinning
84	    #[default]
85	    None = 0,
86	    /// Pin by the name
87	    ByName = 1,
88	}
