101	impl TryFrom<u32> for PinningType {
102	    type Error = PinningError;
103	
104	    fn try_from(value: u32) -> Result<Self, Self::Error> {
105	        match value {
106	            0 => Ok(Self::None),
107	            1 => Ok(Self::ByName),
108	            pinning_type => Err(PinningError::Unsupported { pinning_type }),
109	        }
110	    }
