40	pub(crate) fn bpf_create_iter(link_fd: BorrowedFd<'_>) -> io::Result<crate::MockableFd> {
41	    let mut attr = unsafe { mem::zeroed::<bpf_attr>() };
42	
43	    let u = unsafe { &mut attr.iter_create };
44	    u.link_fd = link_fd.as_raw_fd() as u32;
45	
46	    // SAFETY: BPF_ITER_CREATE returns a new file descriptor.
47	    unsafe { fd_sys_bpf(bpf_cmd::BPF_ITER_CREATE, &mut attr) }
48	}
