50	pub(crate) fn bpf_create_map(
51	    name: &CStr,
52	    def: &aya_obj::Map,
53	    btf_fd: Option<BorrowedFd<'_>>,
54	) -> io::Result<crate::MockableFd> {
55	    let mut attr = unsafe { mem::zeroed::<bpf_attr>() };
56	
57	    let u = unsafe { &mut attr.__bindgen_anon_1 };
58	    u.map_type = def.map_type();
59	    u.key_size = def.key_size();
60	    u.value_size = def.value_size();
61	    u.max_entries = def.max_entries();
62	    u.map_flags = def.map_flags();
63	
64	    if let aya_obj::Map::Btf(m) = def {
65	        // Mimic https://github.com/libbpf/libbpf/issues/355
66	        // Currently a bunch of (usually pretty specialized) BPF maps do not support
67	        // specifying BTF types for the key and value.
68	        if let Ok(
69	            bpf_map_type::BPF_MAP_TYPE_PERF_EVENT_ARRAY
70	            | bpf_map_type::BPF_MAP_TYPE_CGROUP_ARRAY
71	            | bpf_map_type::BPF_MAP_TYPE_STACK_TRACE
72	            | bpf_map_type::BPF_MAP_TYPE_ARRAY_OF_MAPS
73	            | bpf_map_type::BPF_MAP_TYPE_HASH_OF_MAPS
74	            | bpf_map_type::BPF_MAP_TYPE_DEVMAP
75	            | bpf_map_type::BPF_MAP_TYPE_DEVMAP_HASH
76	            | bpf_map_type::BPF_MAP_TYPE_CPUMAP
77	            | bpf_map_type::BPF_MAP_TYPE_XSKMAP
78	            | bpf_map_type::BPF_MAP_TYPE_SOCKMAP
79	            | bpf_map_type::BPF_MAP_TYPE_SOCKHASH
80	            | bpf_map_type::BPF_MAP_TYPE_QUEUE
81	            | bpf_map_type::BPF_MAP_TYPE_STACK
82	            | bpf_map_type::BPF_MAP_TYPE_RINGBUF,
83	        ) = u.map_type.try_into()
84	        {
85	            u.btf_key_type_id = 0;
86	            u.btf_value_type_id = 0;
87	            u.btf_fd = 0;
88	        } else {
89	            u.btf_key_type_id = m.def.btf_key_type_id;
90	            u.btf_value_type_id = m.def.btf_value_type_id;
91	            u.btf_fd = btf_fd.map(|fd| fd.as_raw_fd()).unwrap_or_default() as u32;
92	        }
93	    }
94	
95	    // https://github.com/torvalds/linux/commit/ad5b177bd73f5107d97c36f56395c4281fb6f089
96	    // The map name was added as a parameter in kernel 4.15+ so we skip adding it on
