        override_syscall(|call| match call {
            Syscall::Ebpf {
                cmd: bpf_cmd::BPF_MAP_LOOKUP_ELEM,
                ..
            } => sys_error(ENOENT),
            _ => sys_error(EFAULT),
        });

        assert_matches!(
            bloom_filter.contains(&mut 1, 0),
            Err(MapError::ElementNotFound)
        );
    }
}
