use aya_ebpf_cty::c_long;

use crate::{
    bindings::bpf_map_type::BPF_MAP_TYPE_BLOOM_FILTER,
    helpers::{bpf_map_peek_elem, bpf_map_push_elem},
};

/// A BTF-compatible BPF bloom filter.
///
/// Bloom filters have no key; they store a set of values of type `T`. The
/// number of hash functions used by the filter is provided via the
/// `HASH_FUNCS` const generic, which maps to the map's `map_extra` field.
///
/// # Example
///
/// ```rust
/// use aya_ebpf::{btf_maps::BloomFilter, macros::btf_map};
///
/// #[btf_map]
/// static BLOOM_FILTER: BloomFilter<u32, 10> = BloomFilter::new();
/// ```
// repr(C) is required to ensure fields maintain their declared order in BTF.
// Without it, Rust may reorder fields and libbpf will fail to parse the map
// definition.
#[repr(C)]
pub struct BloomFilter<
    T,
    const MAX_ENTRIES: usize,
    const FLAGS: usize = 0,
    const HASH_FUNCS: usize = 0,
> {
    r#type: *const [i32; BPF_MAP_TYPE_BLOOM_FILTER as usize],
    value: *const T,

    max_entries: *const [i32; MAX_ENTRIES],
    map_flags: *const [i32; FLAGS],
    map_extra: *const [i32; HASH_FUNCS],
}

unsafe impl<T, const MAX_ENTRIES: usize, const FLAGS: usize, const HASH_FUNCS: usize> Sync
    for BloomFilter<T, MAX_ENTRIES, FLAGS, HASH_FUNCS>
{
}

impl<T, const MAX_ENTRIES: usize, const FLAGS: usize, const HASH_FUNCS: usize> Default
    for BloomFilter<T, MAX_ENTRIES, FLAGS, HASH_FUNCS>
{
    fn default() -> Self {
        Self::new()
    }
}

impl<T, const MAX_ENTRIES: usize, const FLAGS: usize, const HASH_FUNCS: usize>
    BloomFilter<T, MAX_ENTRIES, FLAGS, HASH_FUNCS>
{
    pub const fn new() -> Self {
        Self {
            r#type: ptr::null(),
            value: ptr::null(),

            max_entries: ptr::null(),
            map_flags: ptr::null(),
            map_extra: ptr::null(),
        }
    }

    #[inline(always)]
    const fn as_ptr(&self) -> *mut core::ffi::c_void {
        ptr::from_ref(self).cast_mut().cast()
    }

    /// Query the existence of the element.
    #[inline]
    pub fn contains(&self, value: impl Borrow<T>) -> Result<(), c_long> {
        let ret = unsafe {
            bpf_map_peek_elem(
                self.as_ptr(),
                ptr::from_ref(value.borrow()).cast_mut().cast(),
            )
        };
        (ret == 0).then_some(()).ok_or(ret)
    }

    /// Inserts a value into the bloom filter.
    #[inline]
    pub fn insert(&self, value: impl Borrow<T>, flags: u64) -> Result<(), c_long> {
        let ret = unsafe {
            bpf_map_push_elem(self.as_ptr(), ptr::from_ref(value.borrow()).cast(), flags)
        };
        (ret == 0).then_some(()).ok_or(ret)
    }
}
